// ============================================================
// Rule: CTX_Stealer Behavior - Sensitive Wallet Data Staging in AppData
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_Stealer Behavior - Sensitive Wallet Data Staging in AppData.
// Severity: SEV_040_HIGH
// Category: COLLECTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0009 - Collection
// Technique: T1005 - Data from Local System

// Title: CTX - Stealer Behavior - Sensitive Wallet Data Staging in AppData
// Description: Detecta processos não autorizados criando ou modificando arquivos em diretórios de carteiras
// cripto e dados sensíveis dentro de AppData\Roaming. Útil para comportamento de stealers.
// MITRE ATT&CK: T1005 (Data from Local System), T1074.001 (Local Data Staging), T1555 (Credentials from Password Stores)
//
// NOTA TH: Stealers modernos (Vidar, RedLine, Lumma) buscam especificamente estes diretórios.
// O padrão típico é: processo de baixa reputação + acesso a múltiplos dirs de wallet em curto intervalo.
// Para TH proativo, combinar com busca de conexões externas pelo mesmo processo no mesmo período.
// Pivô recomendado: actor_process_image_sha256 → VirusTotal / XSIAM Threat Intel.
//
// ALERT_CATEGORY CORRIGIDO [v2]: "COLLECTION" não é categoria válida no XSIAM.
// Categoria corrigida para CREDENTIAL_ACCESS (tática do T1555 — mais precisa para credenciais de wallet).
//
// CORREÇÃO [v2]: Exclusão de processo legítimo alterada para usar contains em vez de nome exato.
// Nomes hardcoded com versão (ex: electrum-4.7.2.exe) quebram a cada atualização de software.
// Solução mais robusta: usar actor_process_signature_status = "SIGNED" como condição de exclusão.

config case_sensitive = false
| dataset = xdr_data

| filter agent_os_type = ENUM.AGENT_OS_WINDOWS
| filter event_type = ENUM.FILE
    and event_sub_type in (ENUM.FILE_WRITE, ENUM.FILE_CREATE_NEW)

| fields
    _time,
    agent_hostname,
    agent_ip_addresses,
    actor_effective_username,
    actor_process_image_name,
    actor_process_image_path,
    actor_process_command_line,
    actor_process_image_sha256,
    actor_process_signature_status,
    action_file_path,
    action_file_name,
    causality_actor_process_image_name,
    causality_actor_process_command_line

| alter file_path_l = lowercase(action_file_path)

// Diretórios de carteiras cripto comumente visados por stealers
// Nota: carteiras de browser (Metamask, Phantom) ficam em perfil do browser, não aqui
| filter file_path_l ~= "\\\\appdata\\\\roaming\\\\(armory|bytecoin|multibit|exodus|ethereum|electrum|atomic|guarda|walletwasabi|electroncash|sparrow|iocoins?|ppcoin|bbqcoin)\\\\"

// Exclusão de aplicativos legítimos — usando contains para robustez contra atualizações de versão
// Recomendação adicional: filtrar por actor_process_signature_status = "SIGNED" como allowlist mais ampla
| filter actor_process_image_name not contains "Atomic Wallet"
    and actor_process_image_name not contains "Exodus"
    and actor_process_image_name not contains "Sparrow"
    and actor_process_image_name not contains "electrum"

| sort desc _time
